import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)
_MARK = "\x00"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    # Replace each comment with a marker, drop whitespace the removed comment
    # left at the end of a line, then remove any remaining markers.
    text = COMMENT.sub(_MARK, text)
    text = re.sub(r"[ \t]*\x00[ \t]*(?=\r?\n|$)", "", text)
    return text.replace(_MARK, "")


def parse_changelog(text):
    text = strip_comments(text)
    releases = []
    current = None
    for line in text.splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = re.sub(r"\n(?:[ \t]*\n)+", "\n\n", "\n".join(release.body).strip())
            title = f"{release.version} ({release.date})" if release.date else "Unreleased"
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)

